package com.zad.almoslem;
import android.app.Activity;import android.content.SharedPreferences;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.Gravity;import android.view.View;import android.widget.*;
public class TasbeehActivity extends Activity{
private final String[] dhikr={"سبحان الله","الحمد لله","الله أكبر","لا إله إلا الله","أستغفر الله وأتوب إليه","اللهم صلِّ وسلم على نبينا محمد","سبحان الله وبحمده، سبحان الله العظيم","لا حول ولا قوة إلا بالله"};
private SharedPreferences prefs;private int count,goal,index;private TextView number,phrase,progress,target;private ProgressBar bar;private Spinner dhikrPicker,goalPicker;private boolean ready;
private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
private GradientDrawable bg(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
private TextView label(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
private TextView section(String s){TextView t=label(s,14,AppThemeColors.text(this),true);t.setGravity(Gravity.RIGHT);t.setPadding(dp(3),dp(15),dp(3),dp(7));return t;}
private Spinner spinner(String[] values){Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,values);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(adapter);s.setBackground(bg(AppThemeColors.surface(this),12));s.setPadding(dp(10),dp(4),dp(10),dp(4));return s;}
@Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("zad_reminders",MODE_PRIVATE);goal=prefs.getInt("native_tasbeeh_goal",33);count=prefs.getInt("native_tasbeeh_count",0);index=Math.floorMod(prefs.getInt("native_tasbeeh_dhikr",0),dhikr.length);AppThemeColors.apply(this);build();}
private void build(){
ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(14),dp(16),dp(24));root.setBackgroundColor(AppThemeColors.bg(this));scroll.addView(root);
LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setGravity(Gravity.CENTER);hero.setPadding(dp(16),dp(18),dp(16),dp(18));GradientDrawable heroBg=bg(AppThemeColors.primary(this),24);heroBg.setStroke(dp(1),Color.rgb(190,158,91));hero.setBackground(heroBg);
TextView title=label("سبحتك وذكرك",23,Color.WHITE,true);hero.addView(title);TextView subtitle=label("ألا بذكر الله تطمئن القلوب",14,Color.rgb(235,211,157),true);subtitle.setPadding(0,dp(4),0,dp(12));hero.addView(subtitle);
FrameLayout ring=new FrameLayout(this);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(Color.rgb(10,39,34));circle.setStroke(dp(3),Color.rgb(211,177,105));ring.setBackground(circle);number=label("",42,Color.rgb(239,211,151),true);ring.addView(number,new FrameLayout.LayoutParams(dp(142),dp(142),Gravity.CENTER));LinearLayout ringHolder=new LinearLayout(this);ringHolder.setGravity(Gravity.CENTER);ringHolder.addView(ring,new LinearLayout.LayoutParams(dp(154),dp(154)));hero.addView(ringHolder);
target=label("",13,Color.rgb(235,235,221),false);target.setPadding(0,dp(12),0,dp(2));hero.addView(target);progress=label("",12,Color.rgb(220,228,218),false);hero.addView(progress);
bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);if(android.os.Build.VERSION.SDK_INT>=21)bar.setProgressTintList(android.content.res.ColorStateList.valueOf(Color.rgb(218,185,112)));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(6));bp.setMargins(dp(12),dp(10),dp(12),0);hero.addView(bar,bp);root.addView(hero,new LinearLayout.LayoutParams(-1,-2));
root.addView(section("اختر الذكر الذي تريد ترديده"));dhikrPicker=spinner(dhikr);root.addView(dhikrPicker,new LinearLayout.LayoutParams(-1,dp(50)));dhikrPicker.setSelection(index);dhikrPicker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(ready&&index!=pos){index=pos;count=0;save();render();}}});
root.addView(section("حدد هدف التسبيح"));goalPicker=spinner(new String[]{"٣٣ تسبيحة","٦٦ تسبيحة","٩٩ تسبيحة"});root.addView(goalPicker,new LinearLayout.LayoutParams(-1,dp(50)));goalPicker.setSelection(goal==66?1:goal==99?2:0);goalPicker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){int g=new int[]{33,66,99}[pos];if(ready&&goal!=g){goal=g;count=0;save();render();}}});
Button add=new Button(this);add.setText("سَبِّح الآن  •  اضغط للعد");add.setTextSize(17);add.setTextColor(Color.WHITE);add.setAllCaps(false);add.setBackground(bg(Color.rgb(20,105,76),18));LinearLayout.LayoutParams addLp=new LinearLayout.LayoutParams(-1,dp(60));addLp.topMargin=dp(18);root.addView(add,addLp);add.setOnClickListener(v->{if(count<goal)count++;if(count==goal)Toast.makeText(this,"اكتمل العدد، تقبل الله ذكرك",Toast.LENGTH_SHORT).show();save();render();});
Button reset=new Button(this);reset.setText("إعادة ضبط العداد");reset.setAllCaps(false);reset.setTextColor(AppThemeColors.primary(this));reset.setBackground(bg(AppThemeColors.surface(this),14));LinearLayout.LayoutParams resetLp=new LinearLayout.LayoutParams(-1,dp(48));resetLp.topMargin=dp(8);root.addView(reset,resetLp);reset.setOnClickListener(v->{count=0;save();render();});
TextView hint=label("اختيار الذكر والعدد بيدك، ولن ينتقل العداد إلى ذكر آخر تلقائيًا.",12,AppThemeColors.muted(this),false);hint.setPadding(dp(8),dp(14),dp(8),0);root.addView(hint);
setContentView(AppTabs.wrap(this,scroll,"tasbeeh"));ready=true;render();
}
private void save(){prefs.edit().putInt("native_tasbeeh_goal",goal).putInt("native_tasbeeh_count",count).putInt("native_tasbeeh_dhikr",index).apply();}
private void render(){phrase.setText(dhikr[index]);number.setText(String.valueOf(count));target.setText("الهدف: "+goal+" مرة");progress.setText("أنجزت "+count+" من "+goal);bar.setProgress((int)(100f*count/Math.max(1,goal)));}
}